model Request {
  // required fields: id String (@id); title String; status String; approverId String; approver Approver (@relation, fields: [approverId])
  id        String  @id @default(cuid())
  title     String
  status    String @default("draft")
  approverId String
  approver  Approver @relation(fields: [approverId], references: [id])
}
